<?php require_once __DIR__.'/db.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT b.*,c.name customer_name,c.phone FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.id=?");$s->execute([$id]);$b=$s->fetch();if(!$b)die('Bill not found.');$s=$pdo->prepare("SELECT * FROM bill_items WHERE bill_id=? ORDER BY id");$s->execute([$id]);$items=$s->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title><?=e($b['bill_number'])?></title><link rel="stylesheet" href="assets/style.css"></head><body><main class="wrap"><div class="invoice"><div class="invhead"><div><h2>PRODUCT BILL</h2><p>Thank you for shopping with us</p></div><div><b>Bill No:</b> <?=e($b['bill_number'])?><br><b>Date:</b> <?=e($b['created_at'])?></div></div><div class="customer"><b>Customer:</b> <?=e($b['customer_name'])?><br><b>Phone:</b> <?=e($b['phone'])?></div><table><tr><th>Product</th><th class="num">Price</th><th class="num">Qty</th><th class="num">Amount</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['product_name'])?></td><td class="num"><?=money((float)$i['price'])?></td><td class="num"><?=$i['quantity']?></td><td class="num"><?=money((float)$i['amount'])?></td></tr><?php endforeach;?></table><div class="totalbox"><div class="r"><span>Subtotal</span><b><?=money((float)$b['subtotal'])?></b></div><div class="r"><span>Discount (<?=$b['discount_percent']?>%)</span><b>- <?=money((float)$b['discount_amount'])?></b></div><div class="r"><span>GST (<?=$b['gst_percent']?>%)</span><b><?=money((float)$b['gst_amount'])?></b></div><div class="r grand"><span>GRAND TOTAL</span><b><?=money((float)$b['total'])?></b></div></div><div class="thank">Thank You! Visit Again.</div><div class="no-print actions"><button class="btn primary" onclick="window.print()">Print Bill</button><a class="btn light" href="index.php#bills">Back</a></div></div></main></body></html>